/// The full commit id this binary was built from, `None` for a build
/// with no git checkout to read, a source package's.
///
/// `build.rs` takes it from `VC_X1_BUILD_COMMIT`, which `vc-x1
/// install` and `vc-x1 validate` pass, else from git's `HEAD`, and
/// reruns when either changes.
pub fn build_commit() -> Option<&'static str> {
    option_env!("VC_X1_COMMIT").filter(|c| !c.is_empty())
}

/// Whether `@` was empty when this binary was built: `Some` when
/// vc-x1 passed the fact, `None` when it is unknown, the commit having
/// come from `HEAD`.
pub fn build_clean() -> Option<bool> {
    match option_env!("VC_X1_CLEAN") {
        Some("true") => Some(true),
        Some("false") => Some(false),
        _ => None,
    }
}

/// The banner's build metadata: `+<12-char commit>`, then `.dirty`
/// when `@` was not empty or `.unknown` when it was not checked, or
/// empty for a build with no commit.
pub fn build_metadata() -> String {
    render_build_metadata(build_commit(), build_clean())
}

/// [`build_metadata`] over explicit facts, for the tests.
fn render_build_metadata(commit: Option<&str>, clean: Option<bool>) -> String {
    match commit {
        None => String::new(),
        Some(c) => {
            let short = &c[..c.len().min(12)];
            let state = match clean {
                Some(true) => "",
                Some(false) => ".dirty",
                None => ".unknown",
            };
            format!("+{short}{state}")
        }
    }
}

/// The `vc-x1 version` line for the build's provenance.
fn build_line(commit: Option<&str>, clean: Option<bool>) -> String {
    match commit {
        None => "build none: no git checkout to read the commit from".to_string(),
        Some(c) => match clean {
            Some(true) => format!("build {c}, `@` empty"),
            Some(false) => format!("build {c}, `@` not empty, so not exactly that commit"),
            None => format!("build {c}, `@` not checked, a build vc-x1 did not make"),
        },
    }
}

/// The jj-lib version this binary links against.
pub fn jj_lib_version() -> &'static str {
    env!("JJ_LIB_VERSION")
}

