/// acts on, and the error names the four scopes.
#[test]
fn parse_without_scope_errors() {
    use clap::Parser;
    #[derive(Parser)]
    struct Cli {
        #[command(flatten)]
        args: SyncArgs,
    }
    let err = match Cli::try_parse_from(["test"]) {
        Ok(_) => panic!("a bare sync parsed"),
        Err(e) => e.to_string(),
    };
    assert!(err.contains("--scope"), "{err}");
