//! The `install` subcommand: deploy the staged release onto the PATH,
//! the one command that touches it, after checking it is exactly what
//! landed.
//!
//! - The staged binary is `[build] release-bin`, which `vc-x1 build`
//!   made, with its stamp beside it. The destination is
//!   `[install] dir`, `~` expanded, so the committed value fits every
//!   machine, and the binary keeps its file name there.
//! - Every check runs and every failure is listed before anything is
//!   copied, and any failure refuses: `@-` is `main` and `main` is at
//!   `main@origin`, `@` is empty, the manifest's version is bare, the
//!   stamp names `main@origin`'s commit with state `clean`, the stamp's
//!   size and modification time are the binary's, and the binary's
//!   `-V` shows the manifest's version and, when it reports one, the
//!   stamp's commit with no state after it.
//! - The copy is a temporary file beside the destination renamed into
//!   place, so the binary deployed is the one tested, a running copy of
//!   the old one is undisturbed, and a failed copy leaves the old one.
//! - `--dry-run` runs the checks and says what it would copy.
//! - A workspace with no `[install] dir` has nothing to deploy, and
//!   install says so.

use std::path::{Path, PathBuf};

use clap::Args;
use log::{debug, info};

use crate::build_cmd::{BinaryId, release_bin, stamp_path};
use crate::context::Context;
use crate::options_flags::dry_run::DryRunFlag;
use crate::subcommand::SubcommandRunner;
use crate::version::SourceState;

/// The trunk a release is installed from.
const TRUNK: &str = "main";

/// Deploy the staged release onto the PATH.
#[derive(Args, Debug)]
pub struct InstallArgs {
    #[command(flatten)]
    pub dry_run: DryRunFlag,

    /// Workspace to install from [default: the workspace containing
    /// the current directory]
    #[arg(short = 'R', long, value_name = "DIR")]
    pub repo: Option<PathBuf>,
}

/// What the stamp beside the staged binary records, as read back.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StampRecord {
    /// The commit the release was built from.
    pub commit: String,
    /// The state of the source code that was compiled.
    pub state: Option<SourceState>,
    /// The binary's identity when it was stamped.
    pub id: Option<BinaryId>,
}

/// What the staged binary's `-V` says: its version and, from the build
/// metadata after `+`, its commit and the state after it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reported {
    /// The version before any `+`.
    pub version: String,
    /// The commit prefix after `+`, when the build reports one.
    pub commit: Option<String>,
    /// The state after the commit, `dirty` or `unknown`, when not clean.
    pub state: Option<String>,
}

/// Everything the checks judge, gathered before any is made.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Facts {
    /// The full commit id of the work repo's `@-`.
    pub at_parent: String,
    /// The local trunk's commit, `None` when there is no such bookmark.
    pub trunk: Option<String>,
    /// The remote trunk's commit, `None` when it is not known.
    pub trunk_origin: Option<String>,
    /// True when the work repo's `@` is empty.
    pub at_empty: bool,
    /// The manifest's version.
    pub version: String,
    /// The stamp, `None` when there is none.
    pub stamp: Option<StampRecord>,
    /// The staged binary's identity, `None` when it is missing.
    pub bin_id: Option<BinaryId>,
    /// What the staged binary's `-V` said, `None` when it could not be
    /// run or read.
    pub reported: Option<Reported>,
    /// True when the destination directory exists.
    pub dest_dir_exists: bool,
}

/// Per-invocation install inputs: where the staged binary is, where it
/// goes, the facts the checks judge, and whether to copy.
#[derive(Debug)]
pub struct InstallParams {
    /// The staged binary, `[build] release-bin`.
    pub bin: PathBuf,
    /// The destination, `[install] dir` joined with the binary's name.
    pub dest: PathBuf,
    /// What the checks judge.
    pub facts: Facts,
    /// Check and say what would be copied, copying nothing.
    pub dry_run: bool,
}

impl TryFrom<&InstallArgs> for InstallParams {
    type Error = String;

    /// Resolve the workspace, the staged binary, and the destination,
    /// and gather the facts. A missing config key is an error here, and
    /// every fact about the release is left for the checks to judge.
    fn try_from(a: &InstallArgs) -> Result<Self, String> {
        let root = match &a.repo {
            Some(p) => crate::common::find_workspace_root_from(p)
                .ok_or_else(|| format!("install: '{}' is not in a vc-x1 workspace", p.display()))?,
            None => crate::common::find_workspace_root()
                .ok_or_else(|| "install: not in a vc-x1 workspace (no config found)".to_string())?,
        };
        let bin = release_bin(&root).map_err(|e| e.replacen("build:", "install:", 1))?;
        let dest_dir = install_dir(&root)?;
        let name = bin
            .file_name()
            .ok_or_else(|| format!("install: '{}' names no file", bin.display()))?;
        let dest = dest_dir.join(name);
        let facts = Facts {
            at_parent: crate::jj::cid_of(&root, "@-")
                .map_err(|e| format!("install: the commit `@-`: {e}"))?,
            trunk: crate::jj::cid_of(&root, TRUNK).ok(),
            trunk_origin: crate::jj::cid_of(&root, &format!("{TRUNK}@origin")).ok(),
            at_empty: crate::jj::is_empty(&root, "@")
                .map_err(|e| format!("install: whether `@` is empty: {e}"))?,
            version: manifest_version(&root)?,
            stamp: read_stamp(&stamp_path(&bin)),
            bin_id: BinaryId::of(&bin).ok(),
            reported: run_version(&bin).as_deref().and_then(parse_reported),
            dest_dir_exists: dest_dir.is_dir(),
        };
        Ok(InstallParams {
            bin,
            dest,
            facts,
            dry_run: a.dry_run.value,
        })
    }
}

/// `[install] dir` at `root`: `~` and `~/...` against the home
/// directory, any other relative value against the config file's
/// directory, an absolute one as is. Its absence is the workspace
/// having nothing to deploy.
pub fn install_dir(root: &Path) -> Result<PathBuf, String> {
    let cfg = crate::config_md::load(root)
        .map_err(|e| format!("install: {e}"))?
        .ok_or_else(|| format!("install: no config in '{}'", root.display()))?;
    let value = crate::toml_simple::toml_get(&cfg.map, "install.dir").ok_or_else(|| {
        format!(
            "install: {}: no `install.dir`, so this workspace has nothing to deploy. Name the \
             directory the staged release is copied into, such as `~/.cargo/bin` (see `vc-x1 \
             config work`)",
            cfg.path.display()
        )
    })?;
    // OK: a loaded config's path is a file, so it has a parent
    let cfg_dir = cfg.path.parent().unwrap_or(root);
    expand_dir(cfg_dir, value, crate::jj::session::home_dir().as_deref())
}

/// Expand an `[install] dir` value: `~` against `home`, else against
/// `cfg_dir` when relative.
fn expand_dir(cfg_dir: &Path, value: &str, home: Option<&Path>) -> Result<PathBuf, String> {
    let rest = if value == "~" {
        Some("")
    } else {
        value.strip_prefix("~/")
    };
    match rest {
        Some(rest) => home
            .map(|h| h.join(rest))
            .ok_or_else(|| format!("install: `install.dir` is '{value}' and HOME is not set")),
        None => Ok(crate::common::resolve_repo_path(cfg_dir, value)),
    }
}

/// The manifest's version, `[package] version` in the `Cargo.toml` at
/// `root`.
pub fn manifest_version(root: &Path) -> Result<String, String> {
    let path = root.join("Cargo.toml");
    let map = crate::toml_simple::toml_load(&path)
        .map_err(|e| format!("install: cannot read '{}': {e}", path.display()))?;
    crate::toml_simple::toml_get(&map, "package.version")
        .cloned()
        .ok_or_else(|| format!("install: '{}' has no `[package] version`", path.display()))
}

/// The stamp at `path` read back, `None` when there is none or it
/// names no commit.
pub fn read_stamp(path: &Path) -> Option<StampRecord> {
    let map = crate::toml_simple::toml_load(path).ok()?;
    let get = |k: &str| crate::toml_simple::toml_get(&map, k);
    let commit = get("commit")?.clone();
    let size = get("size").and_then(|v| v.parse().ok());
    let mtime_ns = get("mtime-ns").and_then(|v| v.parse().ok());
    let id = match (size, mtime_ns) {
        (Some(size), Some(mtime_ns)) => Some(BinaryId { size, mtime_ns }),
        _ => None,
    };
    Some(StampRecord {
        commit,
        state: get("state").and_then(|v| SourceState::parse(v)),
        id,
    })
}

/// Run `bin -V` and return the first line it prints, `None` when it
/// cannot be run or fails.
fn run_version(bin: &Path) -> Option<String> {
    // Register entry 7 (clippy.toml): install runs the staged release
    // itself, `-V` alone, to check the binary it is about to deploy.
    #[allow(clippy::disallowed_methods)]
    let out = std::process::Command::new(bin).arg("-V").output().ok()?;
    if !out.status.success() {
        return None;
    }
    String::from_utf8(out.stdout)
        .ok()?
        .lines()
        .next()
        .map(str::to_string)
}

/// Parse a `-V` line, `<name> <version>[+<commit>[.<state>]] ...`,
/// `None` when it has no second word.
pub fn parse_reported(line: &str) -> Option<Reported> {
    let word = line.split_whitespace().nth(1)?;
    let (version, meta) = match word.split_once('+') {
        Some((v, m)) => (v, Some(m)),
        None => (word, None),
    };
    let (commit, state) = match meta {
        None => (None, None),
        Some(m) => match m.split_once('.') {
            Some((c, s)) => (Some(c.to_string()), Some(s.to_string())),
            None => (Some(m.to_string()), None),
        },
    };
    Some(Reported {
        version: version.to_string(),
        commit,
        state,
    })
}

/// The 12-character form of a commit id, for messages.
fn short(id: &str) -> &str {
    &id[..id.len().min(12)]
}

/// Every reason the facts refuse an install, empty when it may go.
pub fn refusals(f: &Facts, bin: &Path) -> Vec<String> {
    let mut out = Vec::new();
    match (&f.trunk, &f.trunk_origin) {
        (None, _) => out.push(format!("there is no local `{TRUNK}`")),
        (_, None) => out.push(format!("`{TRUNK}@origin` is not known: fetch or push first")),
        (Some(t), Some(o)) => {
            if &f.at_parent != t {
                out.push(format!(
                    "`@-` is {}, not `{TRUNK}` {}: install deploys what landed, so run it on \
                     `{TRUNK}`",
                    short(&f.at_parent),
                    short(t)
                ));
            }
            if t != o {
                out.push(format!(
                    "`{TRUNK}` is {}, not `{TRUNK}@origin` {}: push it first",
                    short(t),
                    short(o)
                ));
            }
        }
    }
    if !f.at_empty {
        out.push("`@` is not empty: the deployed release would not be the landed one".to_string());
    }
    if f.version.contains('-') {
        out.push(format!(
            "the version {} is not bare: a cycle's suffixed build is not a release",
            f.version
        ));
    }
    match &f.stamp {
        None => out.push(format!(
            "no stamp beside '{}': stage the release with `vc-x1 build`",
            bin.display()
        )),
        Some(st) => {
            if let Some(o) = &f.trunk_origin
                && &st.commit != o
            {
                out.push(format!(
                    "the stamp names {}, not `{TRUNK}@origin` {}: restage with `vc-x1 build` on \
                     `{TRUNK}`",
                    short(&st.commit),
                    short(o)
                ));
            }
            if st.state != Some(SourceState::Clean) {
                let word = st.state.map(SourceState::as_str).unwrap_or("missing");
                out.push(format!(
                    "the stamp's state is {word}, not clean: restage with an empty `@`"
                ));
            }
            match (&st.id, &f.bin_id) {
                (_, None) => {}
                (Some(stamped), Some(now)) if stamped == now => {}
                _ => out.push(
                    "the staged binary is not the one stamped, its size or time differ: it was \
                     rebuilt or replaced, so restage with `vc-x1 build`"
                        .to_string(),
                ),
            }
        }
    }
    if f.bin_id.is_none() {
        out.push(format!("no staged binary at '{}'", bin.display()));
    }
    match &f.reported {
        None if f.bin_id.is_some() => {
            out.push("the staged binary's `-V` could not be run or read".to_string())
        }
        None => {}
        Some(r) => {
            if r.version != f.version {
                out.push(format!(
                    "the staged binary reports {}, not the manifest's {}",
                    r.version, f.version
                ));
            }
            if let (Some(c), Some(st)) = (&r.commit, &f.stamp)
                && !st.commit.starts_with(c.as_str())
            {
                out.push(format!(
                    "the staged binary reports commit {c}, not the stamp's {}",
                    short(&st.commit)
                ));
            }
            if let Some(s) = &r.state {
                out.push(format!("the staged binary reports state {s}, not clean"));
            }
        }
    }
    if !f.dest_dir_exists {
        out.push("the `install.dir` directory does not exist".to_string());
    }
    out
}

/// Copy `bin` to `dest` as a temporary file beside it renamed into
/// place, so `dest` is never half written and a running copy of the
/// old binary is undisturbed. The temporary file is removed on failure.
pub fn deploy(bin: &Path, dest: &Path) -> Result<(), String> {
    // OK: dest is a directory joined with a file name, so both exist
    let dir = dest.parent().unwrap_or(Path::new("."));
    let name = dest
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let tmp = dir.join(format!(".{name}.vc-x1-install"));
    let result = std::fs::copy(bin, &tmp)
        .map_err(|e| format!("install: cannot copy to '{}': {e}", tmp.display()))
        .and_then(|_| {
            std::fs::rename(&tmp, dest).map_err(|e| {
                format!(
                    "install: cannot move '{}' into '{}': {e}",
                    tmp.display(),
                    dest.display()
                )
            })
        });
    if result.is_err() {
        std::fs::remove_file(&tmp).ok();
    }
    result
}

impl SubcommandRunner for InstallArgs {
    type Params = InstallParams;

    /// Delegate to the `TryFrom<&InstallArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        InstallParams::try_from(self)
    }

    /// Run the `install` op (`ctx` unused: the op is fully
    /// parameterized by `Params`).
    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        install(params)
    }
}

/// Judge the facts, refusing with every reason at once, then copy the
/// staged binary into place unless it is a dry run.
pub fn install(params: &InstallParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("install: entry params={params:?}");
    let reasons = refusals(&params.facts, &params.bin);
    if !reasons.is_empty() {
        let list: String = reasons.iter().map(|r| format!("\n  - {r}")).collect();
        return Err(format!(
            "install: refused, nothing copied to '{}':{list}",
            params.dest.display()
        )
        .into());
    }
    let what = format!(
        "{} {}",
        params.facts.version,
        params
            .facts
            .stamp
            .as_ref()
            .map(|s| short(&s.commit))
            .unwrap_or("")
    );
    if params.dry_run {
        info!(
            "install: [dry-run] every check passed, would copy '{}' ({what}) to '{}'",
            params.bin.display(),
            params.dest.display()
        );
        return Ok(());
    }
    deploy(&params.bin, &params.dest)?;
    info!(
        "install: deployed '{}' ({what}) to '{}'",
        params.bin.display(),
        params.dest.display()
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{Cli, Commands};
    use clap::Parser;

    const C: &str = "0123456789abcdef0123456789abcdef01234567";
    const ID: BinaryId = BinaryId {
        size: 10,
        mtime_ns: 20,
    };

    /// Facts that pass every check.
    fn good() -> Facts {
        Facts {
            at_parent: C.to_string(),
            trunk: Some(C.to_string()),
            trunk_origin: Some(C.to_string()),
            at_empty: true,
            version: "0.85.7".to_string(),
            stamp: Some(StampRecord {
                commit: C.to_string(),
                state: Some(SourceState::Clean),
                id: Some(ID),
            }),
            bin_id: Some(ID),
            reported: Some(Reported {
                version: "0.85.7".to_string(),
                commit: Some(C[..12].to_string()),
                state: None,
            }),
            dest_dir_exists: true,
        }
    }

    fn refused(f: &Facts) -> String {
        refusals(f, Path::new("tmp/rel/bin/vc-x1")).join("\n")
    }

    /// Unique tempdir.
    fn tempdir(tag: &str) -> PathBuf {
        let ts = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::env::temp_dir().join(format!("vc-x1-install-{tag}-{ts}"));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn flags_parse() {
        let cli = Cli::try_parse_from(["vc-x1", "install", "--dry-run", "-R", "x"]).unwrap();
        match cli.command {
            Some(Commands::Install(a)) => {
                assert!(a.dry_run.value);
                assert_eq!(a.repo, Some(PathBuf::from("x")));
            }
            _ => panic!("expected Install"),
        }
    }

    /// Facts that pass every check are not refused.
    #[test]
    fn a_landed_clean_release_passes() {
        assert_eq!(refused(&good()), "");
    }

    /// Off the trunk, or a trunk not pushed, is refused, naming each.
    #[test]
    fn off_the_trunk_or_unpushed_is_refused() {
        let mut f = good();
        f.at_parent = "f".repeat(40);
        assert!(refused(&f).contains("install deploys what landed"), "{}", refused(&f));
        let mut f = good();
        f.trunk_origin = Some("e".repeat(40));
        let r = refused(&f);
        assert!(r.contains("push it first"), "{r}");
        assert!(r.contains("restage"), "the stamp no longer names origin: {r}");
        let mut f = good();
        f.trunk_origin = None;
        assert!(refused(&f).contains("is not known"));
        let mut f = good();
        f.trunk = None;
        assert!(refused(&f).contains("no local `main`"));
    }

    /// Edits in `@` or a suffixed version are refused.
    #[test]
    fn edits_or_a_suffixed_version_are_refused() {
        let mut f = good();
        f.at_empty = false;
        assert!(refused(&f).contains("`@` is not empty"));
        let mut f = good();
        f.version = "0.85.7-3".to_string();
        let r = refused(&f);
        assert!(r.contains("is not bare"), "{r}");
        assert!(r.contains("not the manifest's"), "the binary disagrees too: {r}");
    }

    /// A missing stamp, a dirty one, or one not describing the binary
    /// is refused.
    #[test]
    fn the_stamp_must_describe_a_clean_landed_build() {
        let mut f = good();
        f.stamp = None;
        assert!(refused(&f).contains("no stamp beside"));
        let mut f = good();
        f.stamp.as_mut().unwrap().state = Some(SourceState::Dirty);
        assert!(refused(&f).contains("state is dirty"));
        let mut f = good();
        f.bin_id = Some(BinaryId {
            size: 11,
            mtime_ns: 20,
        });
        assert!(refused(&f).contains("rebuilt or replaced"));
        let mut f = good();
        f.stamp.as_mut().unwrap().id = None;
        assert!(refused(&f).contains("rebuilt or replaced"), "an old stamp has no id");
    }

    /// What the binary reports must agree with the manifest and the
    /// stamp, and a binary that reports nothing readable is refused.
    #[test]
    fn the_binary_must_report_the_release() {
        let mut f = good();
        f.reported.as_mut().unwrap().commit = Some("ffffffffffff".to_string());
        assert!(refused(&f).contains("not the stamp's"));
        let mut f = good();
        f.reported.as_mut().unwrap().state = Some("unknown".to_string());
        assert!(refused(&f).contains("reports state unknown"));
        let mut f = good();
        f.reported.as_mut().unwrap().commit = None;
        assert_eq!(refused(&f), "", "a binary reporting no commit passes on the stamp");
        let mut f = good();
        f.reported = None;
        assert!(refused(&f).contains("could not be run"));
        let mut f = good();
        f.bin_id = None;
        f.reported = None;
        let r = refused(&f);
        assert!(r.contains("no staged binary"), "{r}");
        assert!(!r.contains("could not be run"), "one reason for one fault: {r}");
    }

    /// A missing destination directory is refused.
    #[test]
    fn a_missing_destination_is_refused() {
        let mut f = good();
        f.dest_dir_exists = false;
        assert!(refused(&f).contains("does not exist"));
    }

    #[test]
    fn parse_reported_forms() {
        let r = parse_reported("vc-x1 0.85.7+fcc7f222a774 (agent-files v0.3.0)").unwrap();
        assert_eq!(r.version, "0.85.7");
        assert_eq!(r.commit.as_deref(), Some("fcc7f222a774"));
        assert_eq!(r.state, None);
        let r = parse_reported("vc-x1 0.85.7-3+fcc7f222a774.dirty").unwrap();
        assert_eq!(r.version, "0.85.7-3");
        assert_eq!(r.state.as_deref(), Some("dirty"));
        let r = parse_reported("iiac-perf 0.29.2").unwrap();
        assert_eq!((r.version.as_str(), r.commit), ("0.29.2", None));
        assert_eq!(parse_reported("oneword"), None);
    }

    #[test]
    fn expand_dir_forms() {
        let cfg = Path::new("/w");
        let home = Path::new("/home/u");
        assert_eq!(
            expand_dir(cfg, "~/.cargo/bin", Some(home)).unwrap(),
            PathBuf::from("/home/u/.cargo/bin")
        );
        assert_eq!(
            expand_dir(cfg, "~", Some(home)).unwrap(),
            PathBuf::from("/home/u")
        );
        assert_eq!(
            expand_dir(cfg, "/opt/bin", Some(home)).unwrap(),
            PathBuf::from("/opt/bin")
        );
        assert_eq!(
            expand_dir(cfg, "out/bin", Some(home)).unwrap(),
            PathBuf::from("/w/out/bin")
        );
        assert!(expand_dir(cfg, "~/x", None).unwrap_err().contains("HOME"));
        assert_eq!(
            expand_dir(cfg, "~user/x", Some(home)).unwrap(),
            PathBuf::from("/w/~user/x"),
            "only `~` and `~/` expand"
        );
    }

    /// A stamp written by build reads back whole, and a file with no
    /// commit is no stamp.
    #[test]
    fn read_stamp_reads_builds_stamp() {
        let dir = tempdir("stamp");
        let path = dir.join("app.stamp");
        let prov = crate::build_cmd::Provenance {
            commit: C.to_string(),
            state: SourceState::Clean,
        };
        std::fs::write(&path, crate::build_cmd::render_stamp(&prov, ID)).unwrap();
        assert_eq!(
            read_stamp(&path),
            Some(StampRecord {
                commit: C.to_string(),
                state: Some(SourceState::Clean),
                id: Some(ID),
            })
        );
        std::fs::write(&path, "state = \"clean\"\n").unwrap();
        assert_eq!(read_stamp(&path), None);
        assert_eq!(read_stamp(&dir.join("absent")), None);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// The deploy replaces the destination whole and leaves no
    /// temporary file, keeping the binary's permissions.
    #[test]
    fn deploy_replaces_the_destination() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempdir("deploy");
        let bin = dir.join("staged");
        std::fs::write(&bin, "the new release").unwrap();
        std::fs::set_permissions(&bin, std::fs::Permissions::from_mode(0o755)).unwrap();
        let dest_dir = dir.join("bin");
        std::fs::create_dir_all(&dest_dir).unwrap();
        let dest = dest_dir.join("app");
        std::fs::write(&dest, "the old release").unwrap();
        deploy(&bin, &dest).unwrap();
        assert_eq!(std::fs::read_to_string(&dest).unwrap(), "the new release");
        let mode = std::fs::metadata(&dest).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode, 0o755);
        let left: Vec<_> = std::fs::read_dir(&dest_dir).unwrap().collect();
        assert_eq!(left.len(), 1, "no temporary file left");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// A failed copy leaves the destination as it was and no temporary
    /// file.
    #[test]
    fn a_failed_deploy_leaves_the_old_binary() {
        let dir = tempdir("deployfail");
        let dest = dir.join("app");
        std::fs::write(&dest, "the old release").unwrap();
        let e = deploy(&dir.join("absent"), &dest).unwrap_err();
        assert!(e.contains("cannot copy"), "{e}");
        assert_eq!(std::fs::read_to_string(&dest).unwrap(), "the old release");
        assert_eq!(std::fs::read_dir(&dir).unwrap().count(), 1);
        std::fs::remove_dir_all(&dir).ok();
    }
}

