11	//! `build.rs` compiles this file by `#[path]` for the fallback commit
12	//! a build carries when `vc-x1` did not pass one, and the crate
13	//! compiles it for its tests alone.
14	
15	use std::path::{Path, PathBuf};
16	
17	/// The git directory for a checkout at `root`: `root/.git` when it
18	/// is a directory, the `gitdir:` it names when it is a file, `None`
19	/// when there is neither.
20	pub fn git_dir(root: &Path) -> Option<PathBuf> {
21	    let dot_git = root.join(".git");
22	    if dot_git.is_dir() {
23	        return Some(dot_git);
24	    }
25	    let text = std::fs::read_to_string(&dot_git).ok()?;
26	    let target = text.trim().strip_prefix("gitdir:")?.trim();
27	    let path = Path::new(target);
28	    Some(if path.is_absolute() {
29	        path.to_path_buf()
30	    } else {
31	        root.join(path)
32	    })
33	}
