35	/// What `HEAD`'s text says: a commit id, or a ref to resolve.
36	#[derive(Debug, PartialEq, Eq)]
37	pub enum Head {
38	    /// A detached `HEAD`: the commit id itself.
39	    Detached(String),
40	    /// A symbolic `HEAD`: the ref it names, `refs/heads/main`.
41	    Ref(String),
42	}
43	
44	/// Parse `HEAD`'s text, `None` when it is neither form.
45	pub fn parse_head(text: &str) -> Option<Head> {
46	    let text = text.trim();
47	    if let Some(name) = text.strip_prefix("ref:") {
48	        let name = name.trim();
49	        return (!name.is_empty()).then(|| Head::Ref(name.to_string()));
50	    }
51	    is_commit_id(text).then(|| Head::Detached(text.to_string()))
52	}
53	
54	/// True for a full commit id: 40 hex digits (SHA-1) or 64 (SHA-256).
55	pub fn is_commit_id(s: &str) -> bool {
56	    (s.len() == 40 || s.len() == 64) && s.bytes().all(|b| b.is_ascii_hexdigit())
57	}
58	
59	/// The commit `name` points at in `packed-refs` text, `None` when it
60	/// is not listed.
61	pub fn packed_ref(text: &str, name: &str) -> Option<String> {
62	    text.lines()
63	        .filter(|l| !l.starts_with('#') && !l.starts_with('^'))
64	        .find_map(|l| {
65	            let (id, rest) = l.split_once(' ')?;
66	            (rest.trim() == name && is_commit_id(id)).then(|| id.to_string())
67	        })
68	}
69	
70	/// The commit `HEAD` names in the git directory `git_dir`, and the
71	/// files read to find it, so a build script can rerun when any
72	/// changes. The commit is `None` when it cannot be found.
73	pub fn head_commit(git_dir: &Path) -> (Option<String>, Vec<PathBuf>) {
74	    let head_path = git_dir.join("HEAD");
75	    let mut read = vec![head_path.clone()];
76	    let Some(head) = std::fs::read_to_string(&head_path)
77	        .ok()
78	        .and_then(|t| parse_head(&t))
79	    else {
80	        return (None, read);
81	    };
82	    match head {
83	        Head::Detached(id) => (Some(id), read),
84	        Head::Ref(name) => {
85	            let loose = git_dir.join(&name);
86	            if let Ok(text) = std::fs::read_to_string(&loose) {
87	                read.push(loose);
88	                let id = text.trim();
89	                return (is_commit_id(id).then(|| id.to_string()), read);
90	            }
91	            let packed = git_dir.join("packed-refs");
92	            let id = std::fs::read_to_string(&packed)
93	                .ok()
94	                .and_then(|t| packed_ref(&t, &name));
95	            if packed.exists() {
96	                read.push(packed);
97	            }
98	            (id, read)
99	        }
100	    }
101	}
