1	//! The `install` subcommand: deploy the staged release onto the PATH,
2	//! the one command that touches it, after checking it is exactly what
3	//! landed.
4	//!
5	//! - The staged binary is `[build] release-bin`, which `vc-x1 build`
6	//!   made, with its stamp beside it. The destination is
7	//!   `[install] dir`, `~` expanded, so the committed value fits every
8	//!   machine, and the binary keeps its file name there.
9	//! - Every check runs and every failure is listed before anything is
10	//!   copied, and any failure refuses: `@-` is `main` and `main` is at
11	//!   `main@origin`, `@` is empty, the manifest's version is bare, the
12	//!   stamp names `main@origin`'s commit with state `clean`, the stamp's
13	//!   size and modification time are the binary's, and the binary's
14	//!   `-V` shows the manifest's version and, when it reports one, the
15	//!   stamp's commit with no state after it.
16	//! - The copy is a temporary file beside the destination renamed into
17	//!   place, so the binary deployed is the one tested, a running copy of
18	//!   the old one is undisturbed, and a failed copy leaves the old one.
19	//! - `--dry-run` runs the checks and says what it would copy.
20	//! - A workspace with no `[install] dir` has nothing to deploy, and
21	//!   install says so.
22	
23	use std::path::{Path, PathBuf};
24	
25	use clap::Args;
26	use log::{debug, info};
27	
28	use crate::build_cmd::{BinaryId, release_bin, stamp_path};
29	use crate::context::Context;
30	use crate::options_flags::dry_run::DryRunFlag;
31	use crate::subcommand::SubcommandRunner;
32	use crate::version::SourceState;
33	
34	/// The trunk a release is installed from.
35	const TRUNK: &str = "main";
36	
37	/// Deploy the staged release onto the PATH.
38	#[derive(Args, Debug)]
39	pub struct InstallArgs {
40	    #[command(flatten)]
41	    pub dry_run: DryRunFlag,
42	
43	    /// Workspace to install from [default: the workspace containing
