110	impl TryFrom<&InstallArgs> for InstallParams {
111	    type Error = String;
112	
113	    /// Resolve the workspace, the staged binary, and the destination,
114	    /// and gather the facts. A missing config key is an error here, and
115	    /// every fact about the release is left for the checks to judge.
116	    fn try_from(a: &InstallArgs) -> Result<Self, String> {
117	        let root = match &a.repo {
118	            Some(p) => crate::common::find_workspace_root_from(p)
119	                .ok_or_else(|| format!("install: '{}' is not in a vc-x1 workspace", p.display()))?,
120	            None => crate::common::find_workspace_root()
121	                .ok_or_else(|| "install: not in a vc-x1 workspace (no config found)".to_string())?,
122	        };
123	        let bin = release_bin(&root).map_err(|e| e.replacen("build:", "install:", 1))?;
124	        let dest_dir = install_dir(&root)?;
125	        let name = bin
126	            .file_name()
127	            .ok_or_else(|| format!("install: '{}' names no file", bin.display()))?;
128	        let dest = dest_dir.join(name);
129	        let facts = Facts {
130	            at_parent: crate::jj::cid_of(&root, "@-")
131	                .map_err(|e| format!("install: the commit `@-`: {e}"))?,
132	            trunk: crate::jj::cid_of(&root, TRUNK).ok(),
133	            trunk_origin: crate::jj::cid_of(&root, &format!("{TRUNK}@origin")).ok(),
134	            at_empty: crate::jj::is_empty(&root, "@")
135	                .map_err(|e| format!("install: whether `@` is empty: {e}"))?,
136	            version: manifest_version(&root)?,
137	            stamp: read_stamp(&stamp_path(&bin)),
138	            bin_id: BinaryId::of(&bin).ok(),
139	            reported: run_version(&bin).as_deref().and_then(parse_reported),
140	            dest_dir_exists: dest_dir.is_dir(),
141	        };
142	        Ok(InstallParams {
143	            bin,
144	            dest,
145	            facts,
146	            dry_run: a.dry_run.value,
147	        })
148	    }
149	}
