172	/// Expand an `[install] dir` value: `~` against `home`, else against
173	/// `cfg_dir` when relative.
174	fn expand_dir(cfg_dir: &Path, value: &str, home: Option<&Path>) -> Result<PathBuf, String> {
175	    let rest = if value == "~" {
176	        Some("")
177	    } else {
178	        value.strip_prefix("~/")
179	    };
180	    match rest {
181	        Some(rest) => home
182	            .map(|h| h.join(rest))
183	            .ok_or_else(|| format!("install: `install.dir` is '{value}' and HOME is not set")),
184	        None => Ok(crate::common::resolve_repo_path(cfg_dir, value)),
185	    }
186	}
