235	/// Parse a `-V` line, `<name> <version>[+<commit>[.<state>]] ...`,
236	/// `None` when it has no second word.
237	pub fn parse_reported(line: &str) -> Option<Reported> {
238	    let word = line.split_whitespace().nth(1)?;
239	    let (version, meta) = match word.split_once('+') {
240	        Some((v, m)) => (v, Some(m)),
241	        None => (word, None),
242	    };
243	    let (commit, state) = match meta {
244	        None => (None, None),
245	        Some(m) => match m.split_once('.') {
246	            Some((c, s)) => (Some(c.to_string()), Some(s.to_string())),
247	            None => (Some(m.to_string()), None),
248	        },
249	    };
250	    Some(Reported {
251	        version: version.to_string(),
252	        commit,
253	        state,
254	    })
255	}
