394	impl SubcommandRunner for InstallArgs {
395	    type Params = InstallParams;
396	
397	    /// Delegate to the `TryFrom<&InstallArgs>` impl above.
398	    fn to_params(&self) -> Result<Self::Params, String> {
399	        InstallParams::try_from(self)
400	    }
401	
402	    /// Run the `install` op (`ctx` unused: the op is fully
403	    /// parameterized by `Params`).
404	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
405	        install(params)
406	    }
407	}
408	
409	/// Judge the facts, refusing with every reason at once, then copy the
410	/// staged binary into place unless it is a dry run.
411	pub fn install(params: &InstallParams) -> Result<(), Box<dyn std::error::Error>> {
412	    debug!("install: entry params={params:?}");
413	    let reasons = refusals(&params.facts, &params.bin);
414	    if !reasons.is_empty() {
415	        let list: String = reasons.iter().map(|r| format!("\n  - {r}")).collect();
416	        return Err(format!(
417	            "install: refused, nothing copied to '{}':{list}",
418	            params.dest.display()
419	        )
420	        .into());
421	    }
422	    let what = format!(
423	        "{} {}",
424	        params.facts.version,
425	        params
426	            .facts
427	            .stamp
428	            .as_ref()
429	            .map(|s| short(&s.commit))
430	            // OK: unreachable past the checks, which refuse a missing stamp
431	            .unwrap_or("")
432	    );
433	    if params.dry_run {
434	        info!(
435	            "install: [dry-run] every check passed, would copy '{}' ({what}) to '{}'",
436	            params.bin.display(),
437	            params.dest.display()
438	        );
439	        return Ok(());
440	    }
441	    deploy(&params.bin, &params.dest)?;
442	    info!(
443	        "install: deployed '{}' ({what}) to '{}'",
444	        params.bin.display(),
445	        params.dest.display()
446	    );
447	    Ok(())
448	}
