629	        let r = parse_reported("vc-x1 0.85.7-3+fcc7f222a774.dirty").unwrap();
630	        assert_eq!(r.version, "0.85.7-3");
631	        assert_eq!(r.state.as_deref(), Some("dirty"));
632	        let r = parse_reported("iiac-perf 0.29.2").unwrap();
633	        assert_eq!((r.version.as_str(), r.commit), ("0.29.2", None));
634	        assert_eq!(parse_reported("oneword"), None);
635	    }
