1	//! The `install` subcommand: deploy the staged release onto the PATH,
2	//! the one command that touches it, after checking it is exactly what
3	//! landed.
4	//!
5	//! - The staged binary is `[build] release-bin`, which `vc-x1 build`
6	//!   made, with its stamp beside it. The destination is
7	//!   `[install] dir`, `~` expanded, so the committed value fits every
8	//!   machine, and the binary keeps its file name there.
9	//! - Every check runs and every failure is listed before anything is
10	//!   copied, and any failure refuses: `@-` is `main` and `main` is at
11	//!   `main@origin`, `@` is empty, the manifest's version is bare, the
12	//!   stamp names `main@origin`'s commit with state `clean`, the stamp's
13	//!   size and modification time are the binary's, and the binary's
14	//!   `-V` shows the manifest's version and, when it reports one, the
15	//!   stamp's commit with no state after it.
16	//! - The copy is a temporary file beside the destination renamed into
17	//!   place, so the binary deployed is the one tested, a running copy of
18	//!   the old one is undisturbed, and a failed copy leaves the old one.
19	//! - `--dry-run` runs the checks and says what it would copy.
20	//! - A workspace with no `[install] dir` has nothing to deploy, and
21	//!   install says so.
22	
23	use std::path::{Path, PathBuf};
24	
25	use clap::Args;
26	use log::{debug, info};
27	
28	use crate::build_cmd::{BinaryId, release_bin, stamp_path};
29	use crate::context::Context;
30	use crate::options_flags::dry_run::DryRunFlag;
31	use crate::subcommand::SubcommandRunner;
32	use crate::version::SourceState;
33	
34	/// The trunk a release is installed from.
35	const TRUNK: &str = "main";
36	
37	/// Deploy the staged release onto the PATH.
38	#[derive(Args, Debug)]
39	pub struct InstallArgs {
40	    #[command(flatten)]
41	    pub dry_run: DryRunFlag,
42	
43	    /// Workspace to install from [default: the workspace containing
44	    /// the current directory]
45	    #[arg(short = 'R', long, value_name = "DIR")]
46	    pub repo: Option<PathBuf>,
47	}
48	
49	/// What the stamp beside the staged binary records, as read back.
50	#[derive(Debug, Clone, PartialEq, Eq)]
51	pub struct StampRecord {
52	    /// The commit the release was built from.
53	    pub commit: String,
54	    /// The state of the source code that was compiled.
55	    pub state: Option<SourceState>,
56	    /// The binary's identity when it was stamped.
57	    pub id: Option<BinaryId>,
58	}
59	
60	/// What the staged binary's `-V` says: its version and, from the build
61	/// metadata after `+`, its commit and the state after it.
62	#[derive(Debug, Clone, PartialEq, Eq)]
63	pub struct Reported {
64	    /// The version before any `+`.
65	    pub version: String,
66	    /// The commit prefix after `+`, when the build reports one.
67	    pub commit: Option<String>,
68	    /// The state after the commit, `dirty` or `unknown`, when not clean.
69	    pub state: Option<String>,
70	}
71	
72	/// Everything the checks judge, gathered before any is made.
73	#[derive(Debug, Clone, PartialEq, Eq)]
74	pub struct Facts {
75	    /// The full commit id of the work repo's `@-`.
76	    pub at_parent: String,
77	    /// The local trunk's commit, `None` when there is no such bookmark.
78	    pub trunk: Option<String>,
79	    /// The remote trunk's commit, `None` when it is not known.
80	    pub trunk_origin: Option<String>,
81	    /// True when the work repo's `@` is empty.
82	    pub at_empty: bool,
83	    /// The manifest's version.
84	    pub version: String,
85	    /// The stamp, `None` when there is none.
86	    pub stamp: Option<StampRecord>,
87	    /// The staged binary's identity, `None` when it is missing.
88	    pub bin_id: Option<BinaryId>,
89	    /// What the staged binary's `-V` said, `None` when it could not be
90	    /// run or read.
91	    pub reported: Option<Reported>,
92	    /// True when the destination directory exists.
93	    pub dest_dir_exists: bool,
94	}
