96	/// Per-invocation install inputs: where the staged binary is, where it
97	/// goes, the facts the checks judge, and whether to copy.
98	#[derive(Debug)]
99	pub struct InstallParams {
100	    /// The staged binary, `[build] release-bin`.
101	    pub bin: PathBuf,
102	    /// The destination, `[install] dir` joined with the binary's name.
103	    pub dest: PathBuf,
104	    /// What the checks judge.
105	    pub facts: Facts,
106	    /// Check and say what would be copied, copying nothing.
107	    pub dry_run: bool,
108	}
109	
110	impl TryFrom<&InstallArgs> for InstallParams {
111	    type Error = String;
112	
113	    /// Resolve the workspace, the staged binary, and the destination,
114	    /// and gather the facts. A missing config key is an error here, and
115	    /// every fact about the release is left for the checks to judge.
116	    fn try_from(a: &InstallArgs) -> Result<Self, String> {
117	        let root = match &a.repo {
118	            Some(p) => crate::common::find_workspace_root_from(p)
119	                .ok_or_else(|| format!("install: '{}' is not in a vc-x1 workspace", p.display()))?,
120	            None => crate::common::find_workspace_root()
121	                .ok_or_else(|| "install: not in a vc-x1 workspace (no config found)".to_string())?,
122	        };
123	        let bin = release_bin(&root).map_err(|e| e.replacen("build:", "install:", 1))?;
124	        let dest_dir = install_dir(&root)?;
125	        let name = bin
126	            .file_name()
127	            .ok_or_else(|| format!("install: '{}' names no file", bin.display()))?;
128	        let dest = dest_dir.join(name);
129	        let facts = Facts {
130	            at_parent: crate::jj::cid_of(&root, "@-")
131	                .map_err(|e| format!("install: the commit `@-`: {e}"))?,
132	            trunk: crate::jj::cid_of(&root, TRUNK).ok(),
133	            trunk_origin: crate::jj::cid_of(&root, &format!("{TRUNK}@origin")).ok(),
134	            at_empty: crate::jj::is_empty(&root, "@")
135	                .map_err(|e| format!("install: whether `@` is empty: {e}"))?,
136	            version: manifest_version(&root)?,
137	            stamp: read_stamp(&stamp_path(&bin)),
138	            bin_id: BinaryId::of(&bin).ok(),
139	            reported: run_version(&bin).as_deref().and_then(parse_reported),
140	            dest_dir_exists: dest_dir.is_dir(),
141	        };
142	        Ok(InstallParams {
143	            bin,
144	            dest,
145	            facts,
146	            dry_run: a.dry_run.value,
147	        })
148	    }
149	}
150	
151	/// `[install] dir` at `root`: `~` and `~/...` against the home
152	/// directory, any other relative value against the config file's
153	/// directory, an absolute one as is. Its absence is the workspace
154	/// having nothing to deploy.
155	pub fn install_dir(root: &Path) -> Result<PathBuf, String> {
156	    let cfg = crate::config_md::load(root)
157	        .map_err(|e| format!("install: {e}"))?
158	        .ok_or_else(|| format!("install: no config in '{}'", root.display()))?;
159	    let value = crate::toml_simple::toml_get(&cfg.map, "install.dir").ok_or_else(|| {
160	        format!(
161	            "install: {}: no `install.dir`, so this workspace has nothing to deploy. Name the \
162	             directory the staged release is copied into, such as `~/.cargo/bin` (see `vc-x1 \
163	             config work`)",
164	            cfg.path.display()
165	        )
166	    })?;
167	    // OK: a loaded config's path is a file, so it has a parent
168	    let cfg_dir = cfg.path.parent().unwrap_or(root);
169	    expand_dir(cfg_dir, value, crate::jj::session::home_dir().as_deref())
170	}
171	
172	/// Expand an `[install] dir` value: `~` against `home`, else against
173	/// `cfg_dir` when relative.
174	fn expand_dir(cfg_dir: &Path, value: &str, home: Option<&Path>) -> Result<PathBuf, String> {
175	    let rest = if value == "~" {
176	        Some("")
177	    } else {
178	        value.strip_prefix("~/")
179	    };
180	    match rest {
181	        Some(rest) => home
182	            .map(|h| h.join(rest))
183	            .ok_or_else(|| format!("install: `install.dir` is '{value}' and HOME is not set")),
184	        None => Ok(crate::common::resolve_repo_path(cfg_dir, value)),
185	    }
186	}
187	
188	/// The manifest's version, `[package] version` in the `Cargo.toml` at
189	/// `root`.
190	pub fn manifest_version(root: &Path) -> Result<String, String> {
191	    let path = root.join("Cargo.toml");
192	    let map = crate::toml_simple::toml_load(&path)
193	        .map_err(|e| format!("install: cannot read '{}': {e}", path.display()))?;
194	    crate::toml_simple::toml_get(&map, "package.version")
195	        .cloned()
196	        .ok_or_else(|| format!("install: '{}' has no `[package] version`", path.display()))
197	}
198	
199	/// The stamp at `path` read back, `None` when there is none or it
200	/// names no commit.
201	pub fn read_stamp(path: &Path) -> Option<StampRecord> {
202	    let map = crate::toml_simple::toml_load(path).ok()?;
203	    let get = |k: &str| crate::toml_simple::toml_get(&map, k);
204	    let commit = get("commit")?.clone();
205	    let size = get("size").and_then(|v| v.parse().ok());
206	    let mtime_ns = get("mtime-ns").and_then(|v| v.parse().ok());
207	    let id = match (size, mtime_ns) {
208	        (Some(size), Some(mtime_ns)) => Some(BinaryId { size, mtime_ns }),
209	        _ => None,
210	    };
211	    Some(StampRecord {
212	        commit,
213	        state: get("state").and_then(|v| SourceState::parse(v)),
214	        id,
215	    })
216	}
217	
218	/// Run `bin -V` and return the first line it prints, `None` when it
219	/// cannot be run or fails.
220	fn run_version(bin: &Path) -> Option<String> {
221	    // Register entry 7 (clippy.toml): install runs the staged release
222	    // itself, `-V` alone, to check the binary it is about to deploy.
223	    #[allow(clippy::disallowed_methods)]
224	    let out = std::process::Command::new(bin).arg("-V").output().ok()?;
225	    if !out.status.success() {
226	        return None;
227	    }
228	    String::from_utf8(out.stdout)
229	        .ok()?
230	        .lines()
231	        .next()
232	        .map(str::to_string)
233	}
234	
235	/// Parse a `-V` line, `<name> <version>[+<commit>[.<state>]] ...`,
236	/// `None` when it has no second word.
237	pub fn parse_reported(line: &str) -> Option<Reported> {
238	    let word = line.split_whitespace().nth(1)?;
239	    let (version, meta) = match word.split_once('+') {
240	        Some((v, m)) => (v, Some(m)),
241	        None => (word, None),
242	    };
243	    let (commit, state) = match meta {
244	        None => (None, None),
245	        Some(m) => match m.split_once('.') {
246	            Some((c, s)) => (Some(c.to_string()), Some(s.to_string())),
247	            None => (Some(m.to_string()), None),
248	        },
249	    };
250	    Some(Reported {
251	        version: version.to_string(),
252	        commit,
253	        state,
254	    })
255	}
256	
257	/// The 12-character form of a commit id, for messages.
258	fn short(id: &str) -> &str {
259	    &id[..id.len().min(12)]
260	}
261	
262	/// Every reason the facts refuse an install, empty when it may go.
263	pub fn refusals(f: &Facts, bin: &Path) -> Vec<String> {
264	    let mut out = Vec::new();
265	    match (&f.trunk, &f.trunk_origin) {
266	        (None, _) => out.push(format!("there is no local `{TRUNK}`")),
267	        (_, None) => out.push(format!(
268	            "`{TRUNK}@origin` is not known: fetch or push first"
269	        )),
270	        (Some(t), Some(o)) => {
271	            if &f.at_parent != t {
272	                out.push(format!(
273	                    "`@-` is {}, not `{TRUNK}` {}: install deploys what landed, so run it on \
274	                     `{TRUNK}`",
275	                    short(&f.at_parent),
276	                    short(t)
277	                ));
278	            }
279	            if t != o {
280	                out.push(format!(
281	                    "`{TRUNK}` is {}, not `{TRUNK}@origin` {}: push it first",
282	                    short(t),
283	                    short(o)
284	                ));
285	            }
286	        }
287	    }
288	    if !f.at_empty {
289	        out.push("`@` is not empty: the deployed release would not be the landed one".to_string());
290	    }
291	    if f.version.contains('-') {
292	        out.push(format!(
293	            "the version {} is not bare: a cycle's suffixed build is not a release",
294	            f.version
295	        ));
296	    }
297	    match &f.stamp {
298	        None => out.push(format!(
299	            "no stamp beside '{}': stage the release with `vc-x1 build`",
300	            bin.display()
301	        )),
302	        Some(st) => {
303	            if let Some(o) = &f.trunk_origin
304	                && &st.commit != o
305	            {
306	                out.push(format!(
307	                    "the stamp names {}, not `{TRUNK}@origin` {}: restage with `vc-x1 build` on \
308	                     `{TRUNK}`",
309	                    short(&st.commit),
310	                    short(o)
311	                ));
312	            }
313	            if st.state != Some(SourceState::Clean) {
314	                // OK: a stamp with no readable state is named as missing, and refused
315	                let word = st.state.map(SourceState::as_str).unwrap_or("missing");
316	                out.push(format!(
317	                    "the stamp's state is {word}, not clean: restage with an empty `@`"
318	                ));
319	            }
320	            match (&st.id, &f.bin_id) {
321	                (_, None) => {}
322	                (Some(stamped), Some(now)) if stamped == now => {}
323	                _ => out.push(
324	                    "the staged binary is not the one stamped, its size or time differ: it was \
325	                     rebuilt or replaced, so restage with `vc-x1 build`"
326	                        .to_string(),
327	                ),
328	            }
329	        }
330	    }
331	    if f.bin_id.is_none() {
332	        out.push(format!("no staged binary at '{}'", bin.display()));
333	    }
334	    match &f.reported {
335	        None if f.bin_id.is_some() => {
336	            out.push("the staged binary's `-V` could not be run or read".to_string())
337	        }
338	        None => {}
339	        Some(r) => {
340	            if r.version != f.version {
341	                out.push(format!(
342	                    "the staged binary reports {}, not the manifest's {}",
343	                    r.version, f.version
344	                ));
345	            }
346	            if let (Some(c), Some(st)) = (&r.commit, &f.stamp)
347	                && !st.commit.starts_with(c.as_str())
348	            {
349	                out.push(format!(
350	                    "the staged binary reports commit {c}, not the stamp's {}",
351	                    short(&st.commit)
352	                ));
353	            }
354	            if let Some(s) = &r.state {
355	                out.push(format!("the staged binary reports state {s}, not clean"));
356	            }
357	        }
358	    }
359	    if !f.dest_dir_exists {
360	        out.push("the `install.dir` directory does not exist".to_string());
361	    }
362	    out
363	}
364	
365	/// Copy `bin` to `dest` as a temporary file beside it renamed into
366	/// place, so `dest` is never half written and a running copy of the
367	/// old binary is undisturbed. The temporary file is removed on failure.
368	pub fn deploy(bin: &Path, dest: &Path) -> Result<(), String> {
369	    // OK: dest is a directory joined with a file name, so both exist
370	    let dir = dest.parent().unwrap_or(Path::new("."));
371	    // OK: dest is joined with the staged binary's file name, so it has one
372	    let name = dest
373	        .file_name()
374	        .map(|n| n.to_string_lossy().into_owned())
375	        .unwrap_or_default();
376	    let tmp = dir.join(format!(".{name}.vc-x1-install"));
377	    let result = std::fs::copy(bin, &tmp)
378	        .map_err(|e| format!("install: cannot copy to '{}': {e}", tmp.display()))
379	        .and_then(|_| {
380	            std::fs::rename(&tmp, dest).map_err(|e| {
381	                format!(
382	                    "install: cannot move '{}' into '{}': {e}",
383	                    tmp.display(),
384	                    dest.display()
385	                )
386	            })
387	        });
388	    if result.is_err() {
389	        std::fs::remove_file(&tmp).ok();
390	    }
391	    result
392	}
