fn names(c: &str, id: Option<&String>) -> bool {
    id.is_some_and(|id| id.starts_with(c))
}

/// The report: what is being copied, one fact per line, for the user
/// to judge. Nothing in it refuses.
pub fn report(f: &Facts) -> Vec<String> {
    let mut out = Vec::new();
    let Some(r) = &f.reported else {
        return out;
    };
    let mut version = format!("version {}", r.version);
    if r.version.contains('-') {
        version.push_str(", a cycle's suffixed version");
    }
    if r.version != f.version {
        version.push_str(&format!(", the manifest's is {}", f.version));
    }
    out.push(version);
    // The binary's own word first, the stamp's when it reports none.
    let commit = r
        .commit
        .clone()
        .or_else(|| f.stamp.as_ref().map(|s| short(&s.commit).to_string()));
    match &commit {
        None => out.push("commit unknown: the binary reports none and there is no stamp".into()),
        Some(c) => {
            let on_trunk = names(c, f.trunk.as_ref());
            let on_origin = names(c, f.trunk_origin.as_ref());
            let where_ = match (on_trunk, on_origin) {
                (true, true) => format!("`{TRUNK}` and `{TRUNK}@origin`"),
                (true, false) => format!("`{TRUNK}`, not yet `{TRUNK}@origin`"),
                (false, true) => format!("`{TRUNK}@origin`, not the local `{TRUNK}`"),
                (false, false) => format!("not `{TRUNK}`"),
            };
            out.push(format!("commit {c}, {where_}"));
        }
    }
    let state = match (&r.commit, &r.state, &f.stamp) {
        (Some(_), Some(s), _) => s.clone(),
        (Some(_), None, _) => "clean".to_string(),
        // OK: a stamp with no readable state reports as unknown
        (None, _, Some(st)) => st.state.map(SourceState::as_str).unwrap_or("unknown").into(),
        (None, _, None) => "unknown".to_string(),
    };
    out.push(format!("state {state}"));
    match &f.stamp {
        None => out.push("no stamp: `vc-x1 build` did not make this binary".to_string()),
        Some(st) => {
            if st.id.is_none() || st.id != f.bin_id {
                out.push(
                    "the stamp does not match the binary: it was rebuilt by hand or replaced \\
                     after `vc-x1 build`"
                        .to_string(),
                );
            } else if let Some(c) = &r.commit
                && !st.commit.starts_with(c.as_str())
            {
                out.push(format!(
                    "the stamp names commit {}, the binary reports {c}",
                    short(&st.commit)
                ));
            } else {
                out.push("the stamp matches the binary".to_string());
            }
        }
    }
    out
}

/// Every reason the copy itself would be wrong, empty when it may go.
pub fn refusals(f: &Facts, bin: &Path, dest: &Path) -> Vec<String> {
    let mut out = Vec::new();
    if f.bin_id.is_none() {
        out.push(format!(
            "no binary at '{}': build it with `vc-x1 build`",
            bin.display()
        ));
    } else if f.reported.is_none() {
        out.push(format!(
            "'{}' -V could not be run or read",
            bin.display()
        ));
    }
    if !f.dest_dir_exists {
        // OK: dest is a directory joined with a file name, so it has a parent
        let dir = dest.parent().unwrap_or(dest);
        out.push(format!(
            "the `install.dir` directory '{}' does not exist",
            dir.display()
        ));
    }
    out
}

