/// would be wrong, then copy the release binary into place unless it
/// is a dry run.
pub fn install(params: &InstallParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("install: entry params={params:?}");
    info!(
        "install: '{}' -> '{}'",
        params.bin.display(),
        params.dest.display()
    );
    for line in report(&params.facts) {
        info!("install:   {line}");
    }
    let reasons = refusals(&params.facts, &params.bin, &params.dest);
    if !reasons.is_empty() {
        let list: String = reasons.iter().map(|r| format!("\\n  - {r}")).collect();
        return Err(format!(
            "install: refused, nothing copied to '{}':{list}",
            params.dest.display()
        )
        .into());
    }
    if params.dry_run {
        info!("install: [dry-run] copied nothing");
        return Ok(());
    }
    deploy(&params.bin, &params.dest)?;
    info!("install: copied");
    Ok(())
}

